\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{pgfplots}
\usepgfplotslibrary{scatter}
\pgfplotsset{compat=1.18}
\pagestyle{empty}

% ── Color Palette (Dark Tech Aesthetic) ──
\definecolor{bgdeep}{HTML}{0A0F1E}         % deep navy background
\definecolor{cardbg}{HTML}{111827}          % card background
\definecolor{cardbg2}{HTML}{1F2937}         % slightly lighter card
\definecolor{textwhite}{HTML}{F9FAFB}       % primary text
\definecolor{textmuted}{HTML}{9CA3AF}       % secondary text
\definecolor{accentblue}{HTML}{2563EB}      % OpenAI blue
\definecolor{accentamber}{HTML}{D97706}     % Anthropic amber
\definecolor{accentteal}{HTML}{0D9488}      % Google teal
\definecolor{accentpurple}{HTML}{7C3AED}    % DeepSeek purple
\definecolor{stathighlight}{HTML}{1E3A8A}   % stat highlight bg
\definecolor{highlighter}{HTML}{FBBF24}     % gold highlight

\pagecolor{bgdeep}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{accentblue}$\blacktriangleright$}}

% ── Card styles (left accent stripe) ──
\tcbset{
  openaicard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accentblue},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentblue},
    coltitle=accentblue, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  anthropiccard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accentamber},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentamber},
    coltitle=accentamber, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  googlecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accentteal},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentteal},
    coltitle=accentteal, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  deepseekcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accentpurple},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentpurple},
    coltitle=accentpurple, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=stathighlight,
    borderline west={6pt}{0pt}{accentblue},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{highlighter},
    coltitle=highlighter, colbacktitle=stathighlight,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=bgdeep, colframe=bgdeep, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{86}{100}\selectfont\bfseries Aider LLM Polyglot Coding}\\[10pt]
  {\fontsize{86}{100}\selectfont\bfseries Leaderboard 2025}\\[16pt]
  {\fontsize{32}{40}\selectfont\color{textmuted} 225 Exercism Exercises × 6 Languages × 30+ Models}\\[8pt]
  {\fontsize{26}{34}\selectfont\color{textmuted} \raggedright
    \colorbox{accentblue}{\parbox{50pt}{\centering OpenAI}} \quad
    \colorbox{accentamber}{\parbox{60pt}{\centering Anthropic}} \quad
    \colorbox{accentteal}{\parbox{50pt}{\centering Google}} \quad
    \colorbox{accentpurple}{\parbox{60pt}{\centering DeepSeek}}
  }
}

% ══ STAT BANNER ══
\posterbox[
  enhanced, colback=bgdeep, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=4pt, bottom=4pt,
  valign=center,
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accentblue!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{accentblue} 88.0\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textwhite} Top Accuracy}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textmuted} GPT-5 (high)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accentteal!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{accentteal} 6}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textwhite} Languages}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textmuted} C++ Go Java JS Python Rust}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accentamber!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{68}{82}\selectfont\bfseries\color{accentamber} 225}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textwhite} Exercises}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textmuted} Exercism Coding Challenges}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ LEADERBOARD TABLE (Full Width) ══
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  halign=center, valign=top,
  borderline={2pt}{0pt}{accentblue!40},
]{name=leaderboard, column=1, span=3, between=row7 and row13}{
  \fontsize{38}{46}\selectfont\bfseries\color{textwhite} Top 15 Models by Accuracy\\[8pt]
  \fontsize{28}{36}\selectfont
  \rowcolors{1}{}{cardbg2}%
  \begin{tabular}{|>{\raggedright\color{textwhite}}p{60pt}|>{\raggedright\color{textwhite}}p{280pt}|>{\centering\color{textwhite}}p{80pt}|>{\centering\color{textwhite}}p{80pt}|>{\centering\color{textwhite}}p{100pt}|>{\centering\color{textwhite}}p{100pt}|}
    \hline
    \rowcolor{stathighlight}
    \fontsize{26}{32}\selectfont\bfseries\color{highlighter}RANK & \fontsize{26}{32}\selectfont\bfseries\color{highlighter}MODEL & \fontsize{26}{32}\selectfont\bfseries\color{highlighter}ACCURACY & \fontsize{26}{32}\selectfont\bfseries\color{highlighter}COST & \fontsize{26}{32}\selectfont\bfseries\color{highlighter}FORMAT & \fontsize{26}{32}\selectfont\bfseries\color{highlighter}EDIT\% \\
    \hline
    \rowcolor{accentblue!20}
    \fontsize{28}{34}\selectfont\color{accentblue}\bfseries 1 & \fontsize{28}{34}\selectfont\color{accentblue}\bfseries GPT-5 (high) & \fontsize{28}{34}\selectfont\bfseries 88.0\% & \$29.08 & diff & 91.6\% \\
    \rowcolor{cardbg2}
    \fontsize{28}{34}\selectfont\color{accentblue} 2 & \fontsize{28}{34}\selectfont\color{accentblue} GPT-5 (medium) & \fontsize{28}{34}\selectfont 86.7\% & \$17.69 & diff & 88.4\% \\
    \rowcolor{accentamber!15}
    \fontsize{28}{34}\selectfont\color{accentamber}\bfseries 3 & \fontsize{28}{34}\selectfont\color{accentamber}\bfseries Claude 4.0 Opus & \fontsize{28}{34}\selectfont\bfseries 85.3\% & \$22.14 & diff-fenced & 97.3\% \\
    \rowcolor{cardbg2}
    \fontsize{28}{34}\selectfont\color{accentamber} 4 & \fontsize{28}{34}\selectfont\color{accentamber} Claude 4.0 Sonnet & \fontsize{28}{34}\selectfont 84.0\% & \$9.47 & diff-fenced & 96.9\% \\
    \rowcolor{accentteal!15}
    \fontsize{28}{34}\selectfont\color{accentteal}\bfseries 5 & \fontsize{28}{34}\selectfont\color{accentteal}\bfseries Gemini 2.5 Pro & \fontsize{28}{34}\selectfont\bfseries 82.7\% & \$4.92 & diff-fenced & 95.1\% \\
    \rowcolor{cardbg2}
    \fontsize{28}{34}\selectfont\color{accentblue} 6 & \fontsize{28}{34}\selectfont\color{accentblue} o3 (high) & \fontsize{28}{34}\selectfont 82.2\% & \$18.35 & diff & 90.7\% \\
    \rowcolor{cardbg2}
    \fontsize{28}{34}\selectfont\color{accentblue} 7 & \fontsize{28}{34}\selectfont\color{accentblue} GPT-5 (low) & \fontsize{28}{34}\selectfont 81.3\% & \$8.12 & diff & 85.8\% \\
    \rowcolor{accentpurple!15}
    \fontsize{28}{34}\selectfont\color{accentpurple}\bfseries 8 & \fontsize{28}{34}\selectfont\color{accentpurple}\bfseries DeepSeek R1-0528 & \fontsize{28}{34}\selectfont\bfseries 80.4\% & \$3.88 & diff-fenced & 93.2\% \\
    \rowcolor{cardbg2}
    \fontsize{28}{34}\selectfont\color{accentamber} 9 & \fontsize{28}{34}\selectfont\color{accentamber} Claude 3.7 Sonnet & \fontsize{28}{34}\selectfont 79.6\% & \$7.81 & diff-fenced & 96.0\% \\
    \rowcolor{cardbg2}
    \fontsize{28}{34}\selectfont\color{accentblue} 10 & \fontsize{28}{34}\selectfont\color{accentblue} o3 (medium) & \fontsize{28}{34}\selectfont 78.7\% & \$10.22 & diff & 89.3\% \\
    \rowcolor{accentteal!15}
    \fontsize{28}{34}\selectfont\color{accentteal} 11 & \fontsize{28}{34}\selectfont\color{accentteal} Gemini 2.5 Flash & \fontsize{28}{34}\selectfont 76.4\% & \$1.28 & diff-fenced & 93.8\% \\
    \rowcolor{cardbg2}
    \fontsize{28}{34}\selectfont\color{accentblue} 12 & \fontsize{28}{34}\selectfont\color{accentblue} GPT-4.1 & \fontsize{28}{34}\selectfont 74.7\% & \$5.60 & diff & 88.0\% \\
    \rowcolor{accentpurple!15}
    \fontsize{28}{34}\selectfont\color{accentpurple} 13 & \fontsize{28}{34}\selectfont\color{accentpurple} DeepSeek V3-0324 & \fontsize{28}{34}\selectfont 72.9\% & \$1.95 & diff-fenced & 91.5\% \\
    \rowcolor{cardbg2}
    \fontsize{28}{34}\selectfont\color{accentamber} 14 & \fontsize{28}{34}\selectfont\color{accentamber} Claude 3.5 Sonnet & \fontsize{28}{34}\selectfont 72.0\% & \$6.33 & diff-fenced & 95.5\% \\
    \rowcolor{cardbg2}
    \fontsize{28}{34}\selectfont\color{accentblue} 15 & \fontsize{28}{34}\selectfont\color{accentblue} o4-mini (high) & \fontsize{28}{34}\selectfont 71.1\% & \$4.47 & diff & 87.2\% \\
    \hline
  \end{tabular}\\[4pt]
  \fontsize{22}{28}\selectfont\color{textmuted}
  \colorbox{accentblue}{\parbox{16pt}{\ }}
  \textbf{OpenAI}
  \quad\colorbox{accentamber}{\parbox{16pt}{\ }}
  \textbf{Anthropic}
  \quad\colorbox{accentteal}{\parbox{16pt}{\ }}
  \textbf{Google}
  \quad\colorbox{accentpurple}{\parbox{16pt}{\ }}
  \textbf{DeepSeek}
}

% ══ COST VS ACCURACY SECTION ══
\posterbox[
  highlightcard, title={Cost vs. Accuracy Trade-Off}
]{name=costaccuracy, column=1, span=2, between=row13 and row18}{
  \fontsize{30}{38}\selectfont
  \begin{minipage}[t]{0.48\linewidth}
    \fontsize{28}{36}\selectfont\color{highlighter}\bfseries Key Insight\\[6pt]
    \fontsize{28}{36}\selectfont\color{textwhite}
    Near-top accuracy at a fraction of the cost:

    \vspace{4pt}
    \colorbox{accentblue!25}{\parbox{0.95\linewidth}{%
      \fontsize{26}{32}\selectfont\color{textwhite}
      \textbf{GPT-5 (medium)}: 86.7\% @ \$17.69 \\
      \fontsize{22}{28}\selectfont\color{textmuted} ~60\% of high variant cost, only 1.3\% less accurate
    }}

    \vspace{6pt}
    \colorbox{accentteal!25}{\parbox{0.95\linewidth}{%
      \fontsize{26}{32}\selectfont\color{textwhite}
      \textbf{Gemini 2.5 Flash}: 76.4\% @ \$1.28 \\
      \fontsize{22}{28}\selectfont\color{textmuted} 23× cheaper than GPT-5 high, still above 75%
    }}

    \vspace{6pt}
    \colorbox{accentpurple!25}{\parbox{0.95\linewidth}{%
      \fontsize{26}{32}\selectfont\color{textwhite}
      \textbf{DeepSeek R1-0528}: 80.4\% @ \$3.88 \\
      \fontsize{22}{28}\selectfont\color{textmuted} Best value in top 10
    }}
  \end{minipage}
  \hfill
  \begin{minipage}[t]{0.48\linewidth}
    \fontsize{28}{36}\selectfont\color{highlighter}\bfseries Cost Brackets (value models)\\[6pt]
    \fontsize{26}{32}\selectfont\color{textwhite}
    \begin{tabular}{|p{180pt}|>{\centering}p{80pt}|>{\centering}p{60pt}|}
      \hline
      \rowcolor{stathighlight}
      \textbf{Cost Range} & \textbf{Best Model} & \textbf{Accuracy} \\
      \hline
      Under \$2 & Gemini 2.5 Flash & 76.4\% \\
      \$2–\$5 & DeepSeek R1-0528 & 80.4\% \\
      \$5–\$10 & Claude 4.0 Sonnet & 84.0\% \\
      \$10–\$20 & GPT-5 (medium) & 86.7\% \\
      \$20+ & GPT-5 (high) & 88.0\% \\
      \hline
    \end{tabular}
  \end{minipage}
}

% ══ EDIT FORMAT SECTION ══
\posterbox[
  googlecard, title={Edit Format Compliance}
]{name=editformat, column=3, between=row13 and row18}{
  \fontsize{30}{38}\selectfont
  \colorbox{stathighlight}{\parbox{0.94\linewidth}{%
    \fontsize{24}{30}\selectfont\color{textwhite}
    diff-fenced models show 93–97\% compliance vs 85–92\% for plain diff
  }}\\[10pt]

  \fontsize{28}{36}\selectfont\color{textwhite}\bfseries Format Leaders:\\[6pt]
  \fontsize{26}{32}\selectfont\color{textwhite}
  \begin{enumerate}[itemsep=8pt]
    \item \colorbox{accentamber!30}{\parbox{0.80\linewidth}{Claude 4.0 Opus: 97.3\%}}
    \item \colorbox{accentamber!30}{\parbox{0.80\linewidth}{Claude 4.0 Sonnet: 96.9\%}}
    \item \colorbox{accentamber!30}{\parbox{0.80\linewidth}{Claude 3.5 Sonnet: 95.5\%}}
  \end{enumerate}\\[8pt]

  \fontsize{26}{32}\selectfont\color{textmuted}
  Higher compliance = more reliable automated pipelines
}

% ══ KEY TAKEAWAYS (Full Width) ══
\posterbox[
  enhanced, colback=bgdeep, boxrule=0pt, arc=0pt,
  left=16pt, right=16pt, top=8pt, bottom=8pt,
  halign=center, valign=top,
  borderline={2pt}{0pt}{accentblue!50},
]{name=takeaways, column=1, span=3, between=row18 and bottom}{
  \fontsize{38}{46}\selectfont\bfseries\color{highlighter} Key Takeaways\\[8pt]
  \fontsize{30}{38}\selectfont
  \begin{tabular}{p{240pt}p{240pt}p{240pt}}
    \centering
    \colorbox{accentblue!30}{\parbox{220pt}{%
      \fontsize{26}{34}\selectfont\color{textwhite}\bfseries GPT-5 leads at 88.0\% \\
      \fontsize{22}{28}\selectfont\color{textmuted} but premium cost of ~\$29 per run
    }} &
    \centering
    \colorbox{accentamber!30}{\parbox{220pt}{%
      \fontsize{26}{34}\selectfont\color{textwhite}\bfseries Claude 4.0 Sonnet: best value \\
      \fontsize{22}{28}\selectfont\color{textmuted} 84\% accuracy at just \$9.47
    }} &
    \centering
    \colorbox{accentteal!30}{\parbox{220pt}{%
      \fontsize{26}{34}\selectfont\color{textwhite}\bfseries Gemini 2.5 Flash: 76.4\% \\
      \fontsize{22}{28}\selectfont\color{textmuted} for only \$1.28 (budget pick)
    }} \\
  \end{tabular}\\[12pt]
  \fontsize{28}{34}\selectfont\color{textmuted}
  Benchmark: 225 Exercism exercises across C++ • Go • Java • JavaScript • Python • Rust
}

\end{tcbposter}
\end{document}

